INSERT INTO dish_pitches (dish_id, pitch, sort_order) VALUES
  ('nasi-goreng', 'The default answer for a reason: smoky, filling, and somehow always right.', 0),
  ('nasi-goreng', 'When you can''t decide, the wok decides for you.', 1),
  ('nasi-goreng', 'Fried rice with a fried egg on top. You already know this is a good idea.', 2),
  ('mie-ayam', 'Springy noodles, sweet-savoury chicken, broth on the side. Cheap comfort done right.', 0),
  ('mie-ayam', 'Add sambal, add pangsit, add happiness.', 1),
  ('mie-ayam', 'The between-classes classic. Fast, warm, never disappointing.', 2),
  ('bakso', 'Hot broth, bouncy meatballs. Rainy-day energy in a bowl.', 0),
  ('bakso', 'A little kecap, a lot of sambal, and the day gets better.', 1),
  ('bakso', 'Some days just need soup. Today sounds like one of them.', 2),
  ('soto-ayam', 'Turmeric broth, shredded chicken, a squeeze of lime. Gentle and bright.', 0),
  ('soto-ayam', 'Light enough for a morning, warm enough for a whole afternoon.', 1),
  ('soto-ayam', 'The bowl that fixes a long day without slowing you down.', 2),
  ('ayam-geprek', 'Crispy chicken, smashed into sambal. Pick your level and be brave.', 0),
  ('ayam-geprek', 'The student budget hero: crunchy, spicy, and very filling.', 1),
  ('ayam-geprek', 'If you want heat, this is the honest answer.', 2),
  ('nasi-padang', 'Rendang, gulai, sambal ijo. A whole feast on one plate.', 0),
  ('nasi-padang', 'Big appetite? Padang has never once left anyone hungry.', 1),
  ('nasi-padang', 'Point at what you want. That''s the whole menu experience.', 2),
  ('sate-ayam', 'Charcoal smoke and peanut sauce. Your nose already said yes.', 0),
  ('sate-ayam', 'Skewers taste better after dark. That''s just science.', 1),
  ('sate-ayam', 'Sweet, smoky, and great for sharing (or not sharing).', 2),
  ('gado-gado', 'Vegetables that actually taste exciting, thanks to that peanut sauce.', 0),
  ('gado-gado', 'Light, fresh, and still satisfying. The smart pick.', 1),
  ('gado-gado', 'Eat your greens without it feeling like a sacrifice.', 2),
  ('pecel-lele', 'Crispy fried catfish, raw sambal, warm rice. Tenda food at its best.', 0),
  ('pecel-lele', 'The tent-stall dinner Depok runs on.', 1),
  ('pecel-lele', 'Crunchy, spicy, cheap. Hard to argue with that.', 2),
  ('martabak-manis', 'Thick, buttery, loaded with chocolate and cheese. Bring friends. Or don''t.', 0),
  ('martabak-manis', 'Dessert that counts as dinner if you believe hard enough.', 1),
  ('martabak-manis', 'Late night plus martabak equals a good decision.', 2),
  ('seblak', 'Chewy krupuk in a fiery kencur broth. Choose your toppings, choose your pain.', 0),
  ('seblak', 'For when you want your mouth to feel something.', 1),
  ('seblak', 'Customisable chaos in a bowl. In a good way.', 2),
  ('indomie', 'It''s 1 a.m. and the warmindo is open. You know what to do.', 0),
  ('indomie', 'The national midnight snack, made better by someone else''s stove.', 1),
  ('indomie', 'Cheap, fast, and exactly what a deadline night needs.', 2),
  ('nasi-uduk', 'Coconut rice, fried chicken, sambal kacang. A proper start to anything.', 0),
  ('nasi-uduk', 'Fragrant rice that makes every side dish better.', 1),
  ('nasi-uduk', 'Breakfast of champions, Betawi edition.', 2),
  ('bubur-ayam', 'Soft, warm, and easy on a sleepy stomach.', 0),
  ('bubur-ayam', 'Stirred or not stirred? Either way, a gentle morning win.', 1),
  ('bubur-ayam', 'The breakfast that feels like being looked after.', 2),
  ('siomay', 'Steamed fish dumplings drowned in peanut sauce. Snack or meal, your call.', 0),
  ('siomay', 'Light enough to keep going, tasty enough to want more.', 1),
  ('siomay', 'The cart outside campus knows what you need.', 2),
  ('pempek', 'Chewy fish cakes with sweet-sour cuko. Tangy in the best way.', 0),
  ('pempek', 'Kapal selam with a whole egg inside. Go big.', 1),
  ('pempek', 'When you want something different from rice and noodles.', 2),
  ('dimsum', 'Little steamed baskets of joy. Order more than you think.', 0),
  ('dimsum', 'Shareable, snackable, and great when you can''t commit to one thing.', 1),
  ('dimsum', 'Hakau, siomay, bakpao: variety on one table.', 2),
  ('ramen', 'Rich broth, chashu, a jammy egg. Worth the little splurge.', 0),
  ('ramen', 'Treat yourself. You''ve had a week.', 1),
  ('ramen', 'Deep, slow-cooked flavour for a not-so-slow price.', 2),
  ('rice-bowl', 'Chicken teriyaki or sambal matah, all in one tidy bowl.', 0),
  ('rice-bowl', 'Easy to eat between classes, easy to like.', 1),
  ('rice-bowl', 'Everything you need, nothing you don''t.', 2),
  ('burger', 'Smashed patty, melted cheese, toasted bun. Sometimes simple wins.', 0),
  ('burger', 'Two hands, no regrets.', 1),
  ('burger', 'A craving this specific deserves to be answered.', 2),
  ('tteokbokki', 'Chewy rice cakes in sweet-spicy gochujang. Drama-watching food.', 0),
  ('tteokbokki', 'Sweet first, spicy second, addictive third.', 1),
  ('tteokbokki', 'Add cheese. Trust the process.', 2),
  ('ayam-bakar', 'Kecap-glazed, charred at the edges, smoky all the way through.', 0),
  ('ayam-bakar', 'The grill does the convincing. You just eat.', 1),
  ('ayam-bakar', 'A proper meal for a proper hunger.', 2);
